mapper.select:
SELECT P.PAYMENT_ID, P.ORDER_ID, P.PAYMENT_STATUS, P.PAYMENT_METHOD, P.PG_TID, P.MERCHANT_UID, P.AMOUNT_TOTAL, P.PAID_AT, O.ORDER_NO, O.RECEIVER_NAME, O.ORDER_STATUS, O.BRANCH_DEPOSIT_STATUS, (SELECT CODE_NM FROM op_code WHERE GROUP_ID = 'R010680' AND CODE = O.BRANCH_DEPOSIT_STATUS) AS BRANCH_DEPOSIT_STATUS_NM, (SELECT GROUP_CONCAT(PRODUCT_NAME) FROM tb_order_items WHERE ORDER_ID = P.ORDER_ID) as productNames FROM tb_payments P JOIN tb_orders O ON P.ORDER_ID = O.ORDER_ID
AND P.PAYMENT_STATUS = #{paymentStatus}
AND P.PAYMENT_METHOD = #{paymentMethod}
AND P.REGIST_DT >= #{startDate}
AND P.REGIST_DT <= #{endDate}
ORDER BY P.REGIST_DT DESC LIMIT 100
